#include "camera_common/native.hpp"
#include "native_capture.hpp"
#include <algorithm>
#include <atomic>
#include <cctype>
#include <cmath>
#include <depthai/depthai.hpp>
#include <depthai/utility/Clock.hpp>
#include <geometry_msgs/msg/transform_stamped.hpp>
#include <camera_interfaces/msg/scene_inference.hpp>
#include <opencv2/imgcodecs.hpp>
#include <map>
#include <opencv2/core.hpp>
#include <sensor_msgs/msg/camera_info.hpp>
#include <sensor_msgs/msg/compressed_image.hpp>
#include <tf2_ros/static_transform_broadcaster.h>
#include <thread>
#include <vector>

using namespace std::chrono_literals;
using namespace camera_native;

class OakCamera final : public rclcpp::Node {
  struct RawOutput {
    std::string name, processing, socket, topic;
    rclcpp::Publisher<Image>::SharedPtr image;
    rclcpp::Publisher<Text>::SharedPtr data, metadata;
    std::shared_ptr<dai::MessageQueue> queue;
  };
  std::shared_ptr<dai::Device> device_;
  std::unique_ptr<dai::Pipeline> graph_;
  std::unique_ptr<OakRuntimeDebug> debug_;
  std::unique_ptr<NativeCapture> native_;
  rclcpp::Publisher<Image>::SharedPtr rgb_, depth_;
  rclcpp::Publisher<sensor_msgs::msg::CompressedImage>::SharedPtr jpeg_;
  std::shared_ptr<dai::MessageQueue> jpeg_queue_;
  rclcpp::Publisher<sensor_msgs::msg::CameraInfo>::SharedPtr info_;
  rclcpp::Publisher<Text>::SharedPtr details_, diagnostics_;
  std::unique_ptr<tf2_ros::StaticTransformBroadcaster> tf_;
  rclcpp::TimerBase::SharedPtr diagnostic_timer_;
  std::map<std::string, RawOutput> raw_;
  std::shared_ptr<dai::MessageQueue> queue_, scene_queue_;
  rclcpp::Publisher<camera_interfaces::msg::SceneInference>::SharedPtr scene_publisher_;
  std::thread scene_worker_;
  std::string scene_revision_;
  int scene_sample_step_=1;
  std::mutex scene_mutex_;
  std::map<int64_t,std::pair<std::shared_ptr<dai::ImgFrame>,std::shared_ptr<dai::ImgFrame>>> scene_pairs_;
  sensor_msgs::msg::CameraInfo calibration_;
  std::thread capture_, raw_worker_, jpeg_worker_;
  std::atomic<bool> stopping_{false}, failed_{false};
  std::string mxid_, focus_, profile_, revision_, frame_, raw_prefix_,
      raw_frame_;
  double fps_, raw_fps_, timeout_, ir_;
  int lens_, width_ = 0, height_ = 0, mono_height_ = 800, queue_depth_ = 1;
  bool enable_full_hd_;
  int jpeg_quality_;
  bool enable_depth_, enable_raw_, extended_ = false, magnetometer_ = false;
  Json settings_;
  std::atomic<uint64_t> frames_published_{0}, publish_ns_{0},
      max_publish_ns_{0};
  uint64_t previous_frames_ = 0;
  Clock::time_point previous_diagnostics_ = Clock::now();

  static std::string kind(dai::ImgFrame::Type type) {
    switch (type) {
    case dai::ImgFrame::Type::RAW8:
      return "RAW8";
    case dai::ImgFrame::Type::GRAY8:
      return "GRAY8";
    case dai::ImgFrame::Type::RAW16:
      return "RAW16";
    case dai::ImgFrame::Type::RAW10:
      return "RAW10";
    case dai::ImgFrame::Type::PACK10:
      return "PACK10";
    case dai::ImgFrame::Type::NV12:
      return "NV12";
    case dai::ImgFrame::Type::BGR888i:
      return "BGR888i";
    case dai::ImgFrame::Type::BGR888p:
      return "BGR888p";
    default:
      throw std::runtime_error("Unsupported native OAK image type");
    }
  }
  builtin_interfaces::msg::Time stamp(const dai::ImgFrame &frame) {
    const auto age = std::chrono::duration_cast<std::chrono::nanoseconds>(
                         dai::Clock::now() - frame.getTimestamp())
                         .count();
    return static_cast<builtin_interfaces::msg::Time>(
        now() - rclcpp::Duration::from_nanoseconds(age));
  }
  void add_raw(dai::Pipeline &pipeline, dai::Node::Output &output,
               const std::string &name, const std::string &processing,
               const std::string &socket, bool limit = true) {
    std::shared_ptr<dai::MessageQueue> export_queue;
    if (limit) {
      auto script = pipeline.create<dai::node::Script>();
      script->setAlias("raw_sampler_"+name);
      script->setProcessor(dai::ProcessorType::LEON_CSS);
      script->inputs["in"].setBlocking(false);
      script->inputs["in"].setMaxSize(2);
      const int stride =
          std::max(1, static_cast<int>(std::ceil(fps_ / raw_fps_)));
      script->setScript("while True:\n    frame = node.io['in'].get()\n    if "
                        "frame.getSequenceNum() % " +
                        std::to_string(stride) +
                        " == 0:\n        node.io['out'].send(frame)\n    del frame\n");
      output.link(script->inputs["in"]);
      export_queue=script->outputs["out"].createOutputQueue(name=="imu"?50:1,false);
    } else
      export_queue=output.createOutputQueue(name=="imu"?50:1,false);
    RawOutput entry;
    entry.queue=export_queue;
    entry.name = name;
    entry.processing = processing;
    entry.socket = socket;
    entry.topic = raw_prefix_ + "/" + (name == "bayer" ? "rgb/bayer" : name == "rgb_video" ? "rgb" : name == "native_depth" ? "depth" : name);
    entry.metadata = create_publisher<Text>(entry.topic + "/metadata",
                                            image_qos(queue_depth_));
    if (name == "imu")
      entry.data = create_publisher<Text>(entry.topic, image_qos(10));
    else
      entry.image =
          create_publisher<Image>(entry.topic, image_qos(queue_depth_));
    raw_.emplace(name, std::move(entry));
  }
  dai::Pipeline pipeline(const dai::CalibrationHandler &factory, int num,
                         int den) {
    dai::Pipeline pipeline(device_);
    if (enable_raw_)
      pipeline.setSippBufferSize(0);
    auto color = pipeline.create<dai::node::ColorCamera>();
    color->setAlias("rgb_camera");
    color->setBoardSocket(dai::CameraBoardSocket::CAM_A);
    color->setResolution(
        dai::ColorCameraProperties::SensorResolution::THE_1080_P);
    color->setIspScale(num, den);
    color->setFps(fps_);
    // Preserve device-native planar preview; interleave directly into the ROS
    // buffer.
    color->setInterleaved(false);
    color->setColorOrder(dai::ColorCameraProperties::ColorOrder::BGR);
    try {
      auto lens = factory.getLensPosition(dai::CameraBoardSocket::CAM_A);
      if (focus_ == "continuous")
        color->initialControl.setAutoFocusMode(
            dai::CameraControl::AutoFocusMode::CONTINUOUS_VIDEO);
      else if (focus_ == "manual")
        color->initialControl.setManualFocus(lens_);
      else if (lens)
        color->initialControl.setManualFocus(lens);
    } catch (const std::exception &error) {
      RCLCPP_WARN(get_logger(), "Focus: %s", error.what());
    }
    std::tie(width_, height_) = color->getIspSize();
    if (enable_raw_ || enable_full_hd_) {
      color->setIspScale(1, 1);
      color->setVideoSize(1920, 1080);
      color->setPreviewSize(width_, height_);
      color->setPreviewKeepAspectRatio(false);
    }
    if (enable_full_hd_) {
      auto encoder = pipeline.create<dai::node::VideoEncoder>();
      encoder->setAlias("rgb_encoder");
      encoder->setDefaultProfilePreset(fps_, dai::VideoEncoderProperties::Profile::MJPEG);
      encoder->setQuality(jpeg_quality_);
      encoder->input.setBlocking(false);
      encoder->input.setMaxSize(1);
      color->video.link(encoder->input);
      jpeg_queue_=encoder->bitstream.createOutputQueue(1,false);
    }
    if (enable_raw_) {
      add_raw(pipeline, color->raw, "bayer", "sensor", "CAM_A");
      add_raw(pipeline, color->video, "rgb_video",
              "ISP colour conversion, NV12", "CAM_A");
      const auto imu_type = device_->getConnectedIMU();
      if (!imu_type.empty()) {
        auto imu = pipeline.create<dai::node::IMU>();
        imu->setAlias("imu");
        imu->enableIMUSensor(dai::IMUSensor::ACCELEROMETER_RAW, 100);
        imu->enableIMUSensor(dai::IMUSensor::GYROSCOPE_RAW, 100);
        magnetometer_ = imu_type.find("BNO") != std::string::npos;
        if (magnetometer_)
          imu->enableIMUSensor(dai::IMUSensor::MAGNETOMETER_RAW, 100);
        imu->setBatchReportThreshold(1);
        imu->setMaxBatchReports(10);
        add_raw(pipeline, imu->out, "imu", "raw motion measurements", "IMU",
                false);
      }
    }
    auto &application = (enable_raw_ || enable_full_hd_) ? color->preview : color->isp;
    if (!enable_depth_) {
      queue_=application.createOutputQueue(1,false);
      return pipeline;
    }
    auto left = pipeline.create<dai::node::MonoCamera>();
    auto right = pipeline.create<dai::node::MonoCamera>();
    left->setAlias("left_camera");right->setAlias("right_camera");
    auto resolution =
        mono_height_ == 400
            ? dai::MonoCameraProperties::SensorResolution::THE_400_P
            : dai::MonoCameraProperties::SensorResolution::THE_800_P;
    left->setBoardSocket(dai::CameraBoardSocket::CAM_B);
    right->setBoardSocket(dai::CameraBoardSocket::CAM_C);
    left->setResolution(resolution);
    right->setResolution(resolution);
    left->setFps(fps_);
    right->setFps(fps_);
    auto configure = [&](std::shared_ptr<dai::node::StereoDepth> stereo) {
      // v3 removed HIGH_DENSITY and its DEFAULT enables new postprocessing.
      // v3 confidence is accepted ABOVE the threshold (v2 was BELOW).
      // Use the pinned RVC2 DENSITY threshold; retain LR/median and raw depth.
      auto &config=*stereo->initialConfig;
      config.setConfidenceThreshold(15);
      config.setSubpixelFractionalBits(3);
      config.setLeftRightCheckThreshold(10);
      config.setMedianFilter(dai::StereoDepthConfig::MedianFilter::KERNEL_5x5);
      config.postProcessing.holeFilling.enable=false;
      config.postProcessing.adaptiveMedianFilter.enable=false;
      config.postProcessing.spatialFilter.enable=false;
      config.postProcessing.temporalFilter.enable=false;
      config.postProcessing.speckleFilter.enable=false;
      config.postProcessing.decimationFilter.decimationFactor=1;
      stereo->setLeftRightCheck(true);
      stereo->setExtendedDisparity(extended_);
      stereo->setSubpixel(!extended_);
      left->out.link(stereo->left);
      right->out.link(stereo->right);
    };
    auto stereo = pipeline.create<dai::node::StereoDepth>();
    stereo->setAlias("stereo_aligned");
    configure(stereo);
    stereo->setDepthAlign(dai::CameraBoardSocket::CAM_A);
    stereo->setOutputSize(width_, height_);
    if (enable_raw_) {
      add_raw(pipeline, left->out, "left", "sensor mono8", "CAM_B");
      add_raw(pipeline, right->out, "right", "sensor mono8", "CAM_C");
      add_raw(pipeline, stereo->rectifiedLeft, "rectified_left",
              "rectified stereo", "CAM_B");
      add_raw(pipeline, stereo->rectifiedRight, "rectified_right",
              "rectified stereo", "CAM_C");
      add_raw(pipeline, stereo->disparity, "disparity",
              "computed stereo disparity (profile-dependent)", "stereo");
      add_raw(pipeline, stereo->confidenceMap, "confidence",
              "DepthAI v3 stereo confidence (higher is better; accepted above 15)", "stereo");
      auto native = pipeline.create<dai::node::StereoDepth>();
      native->setAlias("stereo_native");
      configure(native);
      add_raw(pipeline, native->depth, "native_depth",
              "computed stereo depth, unaligned, millimetres", "CAM_C");
    }
    auto sync = pipeline.create<dai::node::Sync>();
    sync->setAlias("rgbd_sync");
    sync->setSyncThreshold(
        std::chrono::milliseconds(static_cast<int>(500 / fps_)));
    application.link(sync->inputs["rgb"]);
    stereo->depth.link(sync->inputs["depth"]);
    queue_=sync->out.createOutputQueue(1,false);
    if (!scene_revision_.empty()) {
      auto sample = pipeline.create<dai::node::Script>();
      sample->setAlias("scene_sampler");
      sample->setProcessor(dai::ProcessorType::LEON_CSS);
      sample->inputs["in"].setBlocking(false);sample->inputs["in"].setMaxSize(1);
      scene_sample_step_=std::max(1,static_cast<int>(std::ceil(fps_/2.)));
      sample->setScript("while True:\n    frame=node.io['in'].get()\n    if frame.getSequenceNum() % " +
          std::to_string(scene_sample_step_) + ":\n        node.io['out'].send(frame)\n    del frame\n");
      application.link(sample->inputs["in"]);
      auto resize = pipeline.create<dai::node::ImageManip>();resize->setAlias("scene_resize");
      resize->initialConfig->setOutputSize(416,416,dai::ImageManipConfig::ResizeMode::STRETCH);
      resize->initialConfig->setFrameType(dai::ImgFrame::Type::BGR888p);
      resize->inputImage.setBlocking(false);resize->inputImage.setMaxSize(1);
      sample->outputs["out"].link(resize->inputImage);
      auto network = pipeline.create<dai::node::NeuralNetwork>();network->setAlias("scene_yolo26s_seg");
      network->setBlobPath(ament_index_cpp::get_package_share_directory("oakd_pkg")+
          "/vendor/models/yolo26s_seg_416x416.blob");
      network->setNumInferenceThreads(2);network->input.setBlocking(false);network->input.setMaxSize(1);
      resize->out.link(network->input);
      scene_queue_=network->out.createOutputQueue(1,false);
    }
    return pipeline;
  }
  Image::UniquePtr native_image(const std::shared_ptr<dai::ImgFrame> &frame,
                                const std::string &encoding,
                                const builtin_interfaces::msg::Time &timestamp,
                                const std::string &frame_id) {
    // v3 messages share SDK memory with observers. Copy into ROS without mutating it.
    const auto pixels=frame->getData();
    const auto step=frame->getHeight()?pixels.size()/frame->getHeight():0;
    return copy_image(frame->getWidth(), frame->getHeight(), encoding,
                      timestamp, frame_id,pixels.data(),pixels.size(),step);
  }
  void capture_loop() {
    auto last = Clock::now();
    try {
      while (!stopping_ && rclcpp::ok()) {
        std::shared_ptr<dai::ImgFrame> rgb, depth;
        if (enable_depth_) {
          auto group = queue_->tryGet<dai::MessageGroup>();
          if (group) {
            rgb = group->get<dai::ImgFrame>("rgb");
            depth = group->get<dai::ImgFrame>("depth");
          }
        } else
          rgb = queue_->tryGet<dai::ImgFrame>();
        if (!rgb) {
          if (Clock::now() - last > std::chrono::duration<double>(timeout_))
            throw std::runtime_error("OAK-D stopped delivering frames");
          std::this_thread::sleep_for(1ms);
        RCLCPP_ERROR(node_.get_logger(), "Native detection: %s", e.what());
        failed_ = true; rclcpp::shutdown();
      }
    }
  }
public:
  NativeCapture(rclcpp::Node &node, std::atomic<bool> &failed, const std::string &mxid,
                const std::string &id, double fps, const std::string &focus, int lens, int quality)
      : node_(node), failed_(failed), id_(id) {
    using namespace camera_native;
    model_ = parameter(node, "native_model", env("OAK_NATIVE_MODEL", "yolov8n_coco_640x352"));
    auto root = env("OAK_NATIVE_MODEL_DIR", ament_index_cpp::get_package_share_directory("oakd_pkg") + "/vendor/models");
    std::ifstream catalog_file(root + "/catalog.json");
    if (!catalog_file) throw std::invalid_argument("Native model catalog missing: " + root);
    nlohmann::json catalog; catalog_file >> catalog;
    std::vector<float> anchors;
    std::map<std::string, std::vector<int>> anchor_masks;
    int classes = 80;
    bool known = false;
    for (const auto &entry : catalog) if (entry.at("id").get<std::string>() == model_) {
      if (!entry.value("enabled", true))
        throw std::invalid_argument("Native model unavailable: " + entry.value("reason", std::string("not validated")));
      width_ = entry.at("width").get<int>(); height_ = entry.at("height").get<int>();
      classes = entry.value("classes", 80);
      if (classes < 1 || classes > 1000) throw std::invalid_argument("Invalid native model class count");
      anchors = entry.value("anchors", std::vector<float>{});
      anchor_masks = entry.value("anchor_masks", std::map<std::string, std::vector<int>>{});
      known = true; break;
    }
    if (!known) throw std::invalid_argument("Unknown native YOLO model: " + model_);
    auto blob = parameter(node, "native_blob", model_ == "yolov8n_coco_640x352"
      ? env("OAK_NATIVE_BLOB", root + "/" + model_ + ".blob") : root + "/" + model_ + ".blob");
    session_ = parameter(node, "mode_revision", std::string("startup"));
    auto confidence = parameter(node, "native_confidence", .25);
    auto iou = parameter(node, "native_iou", .5);
    if (!std::isfinite(confidence) || confidence<=0 || confidence>1 || !std::isfinite(iou) || iou<=0 || iou>1)
      throw std::invalid_argument("Native confidence and IoU must be in (0,1]");
    if (!std::filesystem::is_regular_file(blob)) throw std::invalid_argument("Native YOLO blob missing: "+blob);
    device_ = std::make_shared<dai::Device>(dai::DeviceInfo(mxid));
    pipeline_ = std::make_unique<dai::Pipeline>(device_);
    auto &pipeline = *pipeline_;
    pipeline.setOpenVINOVersion(dai::OpenVINO::Version::VERSION_2022_1);
    auto color = pipeline.create<dai::node::ColorCamera>();
    color->setAlias("rgb_camera");
    color->setBoardSocket(dai::CameraBoardSocket::CAM_A);
    color->setResolution(dai::ColorCameraProperties::SensorResolution::THE_1080_P);
    color->setVideoSize(1920,1080); color->setPreviewSize(width_,height_);
    color->setPreviewKeepAspectRatio(false); // Stretch full FoV; normalized boxes map directly to Full HD.
    color->setInterleaved(false); color->setColorOrder(dai::ColorCameraProperties::ColorOrder::BGR);
    color->setFps(fps);
    auto nn = pipeline.create<dai::node::DetectionNetwork>();
    nn->setAlias("native_yolo");
    nn->neuralNetwork->setAlias("native_nn");nn->detectionParser->setAlias("native_parser");
    nn->setBlobPath(blob); nn->detectionParser->setNNFamily(DetectionNetworkType::YOLO);
    // Existing blobs use the YOLOv6r2 head contract, regardless of model family.
    nn->detectionParser->setSubtype(anchors.empty()?"yolov6r2":"yolov5");
    nn->detectionParser->setConfidenceThreshold(confidence); nn->detectionParser->setIouThreshold(iou);
    nn->detectionParser->setNumClasses(classes); nn->detectionParser->setCoordinateSize(4);
    nn->detectionParser->setAnchors(anchors); nn->detectionParser->setAnchorMasks(anchor_masks);
    nn->neuralNetwork->setNumInferenceThreads(2); nn->input.setBlocking(false); nn->input.setMaxSize(1);
    color->preview.link(nn->input);
    detections_ = nn->out.createOutputQueue(8,false);
    auto encoder = pipeline.create<dai::node::VideoEncoder>();
    encoder->setAlias("rgb_encoder");
    encoder->setDefaultProfilePreset(fps,dai::VideoEncoderProperties::Profile::MJPEG); encoder->setQuality(quality);
    color->video.link(encoder->input);
    images_ = encoder->bitstream.createOutputQueue(30,false);
    auto logger = pipeline.create<dai::node::SystemLogger>(); logger->setRate(1.);
    logger->setAlias("system_logger");
    telemetry_ = logger->out.createOutputQueue(1,false);
    if (focus == "continuous") color->initialControl.setAutoFocusMode(dai::CameraControl::AutoFocusMode::CONTINUOUS_VIDEO);
    else color->initialControl.setManualFocus(focus == "manual" ? lens : device_->readCalibration().getLensPosition(dai::CameraBoardSocket::CAM_A));
    debug_ = std::make_unique<OakRuntimeDebug>(node,pipeline,id_);
    pipeline.start();debug_->start();
    publisher_ = node.create_publisher<Packet>("/native/"+id_,image_qos(1));
    telemetry_publisher_ = node.create_publisher<std_msgs::msg::String>("/native/"+id_+"/telemetry",image_qos(1));
    worker_ = std::thread([this]{loop();});
    RCLCPP_INFO(node.get_logger(), "On-device %s (%d classes): %s, %dx%d inference, matched Full HD JPEG on /native/%s", model_.c_str(), classes, mxid.c_str(), width_, height_, id_.c_str());
  }
  ~NativeCapture() { stop_=true; if(worker_.joinable())worker_.join();debug_.reset(); if(pipeline_)pipeline_->stop(); if(device_)device_->close(); }
};
FROM ros:jazzy-ros-base

RUN apt-get update && apt-get install -y \
    python3-pip \
    python3-opencv \
    ros-jazzy-cv-bridge \
    ros-jazzy-rviz2 \
    python3-colcon-common-extensions \
    && rm -rf /var/lib/apt/lists/*

RUN python3 -m pip install --break-system-packages \
    "numpy<2" \
    ultralytics \
    lap

RUN mkdir -p /app/models /data/scans

# YOLOE-26L prompt-free: ~4585 clase, cu segmentare (contururi)
RUN cd /app/models && python3 -c "\
from ultralytics.utils.downloads import attempt_download_asset; \
attempt_download_asset('yoloe-26l-seg-pf.pt')"

# Small task-specific defaults are available without runtime network access.
RUN cd /app/models && python3 -c "from ultralytics.utils.downloads import attempt_download_asset; [attempt_download_asset(name) for name in ('yolo26s-seg.pt','yolo26n.pt','yolo26n-seg.pt','yolo26n-pose.pt','yolo26n-obb.pt')]"
RUN mkdir -p /data/models /data/yolo

WORKDIR /app/ros2_ws

COPY ros2_ws/src ./src

RUN . /opt/ros/jazzy/setup.sh && \
    colcon build

RUN echo "source /opt/ros/jazzy/setup.bash" >> /root/.bashrc
RUN echo "source /app/ros2_ws/install/setup.bash" >> /root/.bashrc

COPY entrypoint.sh /app/entrypoint.sh
ENTRYPOINT ["bash", "/app/entrypoint.sh"]
CMD ["ros2", "run", "yolo_pkg", "yolo_dashboard"]
