"""PostgreSQL: scriere in fundal (coada) + interogari pentru pagini."""

import os
import queue
import threading
import time

import psycopg
from psycopg.rows import dict_row


DSN = os.environ.get(
    "DATABASE_URL",
    "postgresql://robot:robot@postgres:5432/robot"
)

# Acelasi track YOLO nevazut atata timp -> obiect nou in DB
TRACK_TIMEOUT_S = 60.0
# Cat de des salvam o observatie per obiect
OBSERVATION_PERIOD_S = 1.0
# Track nou la mai putin de atat de un obiect vazut recent = acelasi obiect
# (cu 4585 de clase eticheta si ID-ul de track "palpaie" pe acelasi lucru)
SAME_OBJECT_DISTANCE_M = 0.15


def detection_position(detection):
    """Pozitia folosita la potrivire: harta daca SLAM e activ, altfel camera."""
    if detection.get("position_map"):
        p = detection["position_map"]
        return "map", (p["x"], p["y"], p["z"])

    if detection.get("position"):
        p = detection["position"]
        return "camera", (p["x"], p["y"], p["z"])

    return None, None


class Database:

    def __init__(self):
        self.queue = queue.Queue(maxsize=2000)
        self.connection = None
        self.lock = threading.Lock()

        # (track_id, name) -> {"db_id", "last_seen", "last_write"}
        self.tracks = {}
        self.last_gesture_write = 0.0
        self.last_pose_write = 0.0

        self.thread = threading.Thread(target=self.writer_loop, daemon=True)
        self.thread.start()

    # ------------------------------------------------------------------ conexiune

    def connect(self):
        while True:
