    def find_nearby(self, frame, position, kind, now):
        """Obiect vazut recent in acelasi loc (persoanele doar cu persoane)."""
        if position is None:
            return None

        best = None
        best_distance = SAME_OBJECT_DISTANCE_M

        for track in {id(t): t for t in self.tracks.values()}.values():
            if now - track["last_seen"] > TRACK_TIMEOUT_S:
                continue

            if track.get("frame") != frame or track["type"] != kind:
                continue

            distance = sum(
                (a - b) ** 2 for a, b in zip(track["position"], position)
            ) ** 0.5

            if distance < best_distance:
                best = track
                best_distance = distance

        return best

