        self.execute(
            "INSERT INTO scans (object_id, track_id, name, file, points, frame_id) "
            "VALUES (%s, %s, %s, %s, %s, %s)",
            (track["db_id"] if track else None, data.get("track_id"),
             data.get("name"), data.get("file"), data.get("points"),
