        now = time.monotonic()

        if now - self.last_pose_write < OBSERVATION_PERIOD_S:
            return

        self.last_pose_write = now

        self.execute(
            "INSERT INTO camera_poses (x, y, z, qx, qy, qz, qw) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s)",
            (pose["x"], pose["y"], pose["z"],
             pose["qx"], pose["qy"], pose["qz"], pose["qw"])
        )

