    def objects(self, kind=None, limit=200):
        sql = "SELECT * FROM tracked_objects"
        params = []

        if kind:
            sql += " WHERE type = %s"
            params.append(kind)

        sql += " ORDER BY last_seen DESC LIMIT %s"
        params.append(limit)

        return self.execute(sql, params, fetch=True)

    def observations(self, object_id, limit=300):
        return self.execute(
            "SELECT * FROM observations WHERE object_id = %s "
            "ORDER BY ts DESC LIMIT %s",
            (object_id, limit),
            fetch=True
        )

    def scans(self):
        return self.execute(
            "SELECT * FROM scans ORDER BY created_at DESC LIMIT 200",
            fetch=True
        )

    def stats(self):
        rows = self.execute(
            "SELECT "
            "(SELECT count(*) FROM tracked_objects WHERE type='object') AS objects, "
            "(SELECT count(*) FROM tracked_objects WHERE type='person') AS persons, "
            "(SELECT count(*) FROM observations) AS observations, "
            "(SELECT count(*) FROM scans) AS scans, "
            "(SELECT count(*) FROM camera_poses) AS camera_poses, "
            "(SELECT count(*) FROM gesture_events) AS gesture_events",
            fetch=True
        )

        return rows[0]

    def trajectory(self, limit=2000):
        return self.execute(
            "SELECT ts, x, y, z FROM camera_poses ORDER BY ts DESC LIMIT %s",
