"""Shared native model catalog; availability is checked before changing ownership."""
import json
import os
from pathlib import Path

DEFAULT_MODEL = 'yolov8n_coco_640x352'


def model_root():
    if os.getenv('OAK_NATIVE_MODEL_DIR'):
        return Path(os.environ['OAK_NATIVE_MODEL_DIR'])
    try:
        from ament_index_python.packages import get_package_share_directory
        return Path(get_package_share_directory('oakd_pkg')) / 'vendor/models'
    except (ImportError, LookupError):
        return Path(__file__).resolve().parents[2] / 'oakd_pkg/vendor/models'


def model_catalog():
    root = model_root()
    records = json.loads((root / 'catalog.json').read_text())
    benchmark_file = root / 'benchmarks.json'
    benchmarks = json.loads(benchmark_file.read_text()) if benchmark_file.is_file() else {}
    for record in records:
        blob = root / (record['id'] + '.blob')
        # Preserve the original nano-only startup override without mislabeling other models.
        if record['id'] == DEFAULT_MODEL and os.getenv('OAK_NATIVE_BLOB'):
            blob = Path(os.environ['OAK_NATIVE_BLOB'])
        record['blob'] = str(blob)
        record['available'] = blob.is_file() and record.get('enabled', True)
        record['reason'] = '' if record['available'] else record.get('reason', 'Compatible RVC2 blob is not installed')
        record['blob_size_mib'] = round(blob.stat().st_size / 1048576, 2) if blob.is_file() else None
        record['benchmark'] = benchmarks.get(record['id'])
    return records


def native_model(model):
    for record in model_catalog():
        if record['id'] == model:
            return record
    raise ValueError('Unknown native YOLO model: ' + str(model))
