LOG = logging.getLogger('camera_ownership')


class Ownership:
    def __init__(self, directory, url, command=None):
        self.directory = Path(directory)
        self.directory.mkdir(parents=True, exist_ok=True)
        self.url = url
        self.command = command or ['ros2', 'launch', 'camera_devices', 'devices.launch.py']
        self.identity = uuid.uuid4().hex
        self.lock = None
        self.child = None
        self.active = False
        self.stopping = threading.Event()
        self.worker = None

    def read_owner(self):
        try:
            return json.loads((self.directory/'owner.json').read_text())
        except (OSError, ValueError):
            return {}

    def status(self):
        return {'role': 'owner' if self.active else 'standby',
                'instance': self.identity, 'owner': self.read_owner(),
                'local_ros_domain_id': os.getenv('ROS_DOMAIN_ID', '0')}

    def publish(self):
        record = {'instance': self.identity, 'url': self.url,
                  'ros_domain_id': os.getenv('ROS_DOMAIN_ID', '0'),
                  'heartbeat': time.time()}
        temporary = self.directory/(self.identity+'.tmp')
        temporary.write_text(json.dumps(record))
        temporary.replace(self.directory/'owner.json')

    def acquire(self):
        # Keep the same inode: never truncate, replace or delete ownership.lock.
        handle = open(self.directory/'ownership.lock', 'a+')
        try:
            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            handle.close()
            return False
        self.lock = handle
        return True

    def marked_processes(self):
        """Also find camera workers orphaned after an unexpected launch exit."""
        marker = ('CAMERA_CAPTURE_OWNER='+self.identity).encode()
        result = []
        for entry in Path('/proc').iterdir():
            if not entry.name.isdigit() or int(entry.name) == os.getpid():
                continue
            try:
                if marker in (entry/'environ').read_bytes().split(b'\0'):
                    # Zombies have already released hardware and file descriptors.
                    if (entry/'stat').read_text().split(') ', 1)[1].split()[0] != 'Z':
                        result.append(int(entry.name))
            except OSError:
                pass
        return result

    def stop_capture(self):
        deadline = time.monotonic()+20
        for pid in self.marked_processes():
            try:
                os.kill(pid, signal.SIGINT)
            except ProcessLookupError:
                pass
        while self.marked_processes() and time.monotonic() < deadline:
            if self.child is not None:
                self.child.poll()
            time.sleep(.1)
        for pid in self.marked_processes():
            try:
                os.kill(pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        if self.child is not None:
            self.child.wait(timeout=5)
            self.child = None
        # Do not unlock while a SIGKILLed USB worker is still exiting.
        deadline = time.monotonic()+5
        while self.marked_processes() and time.monotonic() < deadline:
            time.sleep(.05)
        if self.marked_processes():
            raise RuntimeError('Capture workers have not exited; retaining ownership lock')

    def release(self):
        if self.lock is None:
            return
        self.stop_capture()
        self.active = False
        if self.read_owner().get('instance') == self.identity:
            (self.directory/'owner.json').unlink(missing_ok=True)
        fcntl.flock(self.lock, fcntl.LOCK_UN)
        self.lock.close()
        self.lock = None

    def run(self):
        LOG.info('Checking host camera ownership; standby instances open no cameras')
        try:
            while not self.stopping.is_set():
                if self.lock is None and self.acquire():
                    LOG.warning('Camera ownership acquired: %s', self.identity)
                    env = dict(os.environ, CAMERA_CAPTURE_OWNER=self.identity)
                    self.child = subprocess.Popen(self.command, env=env, start_new_session=True,
                                                  pass_fds=(self.lock.fileno(),))
                    self.active = True
                if self.active:
                    if self.child.poll() is not None:
                        LOG.error('Camera launch exited; cleaning up remaining drivers before retry')
                        self.release()
                        self.stopping.wait(3)
                        continue
                    self.publish()
                self.stopping.wait(1)
        except Exception:
            LOG.exception('Camera ownership supervisor failed')
        finally:
            self.release()

