def model_catalog():
    records = {name: dict(id=name, label=label, task=task, description=description,
                         cached=(MODEL_DIR/name).is_file() or (CUSTOM_DIR/name).is_file(),
                         custom=False)
               for name, label, task, description in BUILTIN_MODELS}
    if CUSTOM_DIR.exists():
        for path in sorted(CUSTOM_DIR.iterdir()):
            if not path.is_file() or path.is_symlink() or path.suffix != '.pt':
                continue
            if path.name in records:
                records[path.name]['cached'] = True
                continue
            task = next((task for suffix, task in [('-seg', 'segment'), ('-pose', 'pose'),
                                                  ('-obb', 'obb'), ('-cls', 'classify')]
                         if suffix in path.stem), 'detect')
            if task == 'classify':
                continue  # A classifier has no object bounding boxes.
            records[path.name] = dict(id=path.name, label=path.stem, task=task, custom=True,
                                      cached=True, description='Custom model')
